    const assigned=id=>queue.filter(o=>o.from===id).reduce((s,o)=>s+o.count,0);
    let roundStartMap=clone(map);
    const available=id=>map[id]?.owner==="human"?Math.max(0,map[id].armies-1-assigned(id)):0;
